scan_linter_check.script:
(function(engine) {
    var kind = new global.EcsContext(engine.current).clientKind();
    if (!engine.rootNode || !kind) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsClientScript(ast, kind).getReferenceCalls();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CLIENT-004',
        title: 'getReference() used in a client script',
        recommendation: 'Use GlideAjax to return only the fields needed, or g_form.getDisplayValue() for a reference\'s display value. getReference() transfers the whole referenced record.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
